import{_ as t,o,c as d,a2 as a}from"./chunks/framework.G0y0PQA7.js";const u=JSON.parse('{"title":"Command line","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/cli.md","filePath":"en/features/cli.md"}'),i={name:"en/features/cli.md"};function r(n,e,c,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h1><p>How to export, import, compare, merge, check and work with databases without a window, using the same executable (<code>relio</code>). It fits well in build scripts and CI.</p><p>The workflow with Git is in <a href="/relio/en/quick/git">Work together and merge with Git</a> in Quick start.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ul><li>The installer does not add <code>relio</code> to the PATH. On Windows, call <code>relio.exe</code> in the installation folder by its full path, or add that folder to the PATH yourself. For the portable version, it is the <code>relio.exe</code> in the folder you unzipped.</li><li>See the options with <code>relio --help</code>, <code>relio export &lt;kind&gt; --help</code>, <code>relio import --help</code>, <code>relio diff --help</code>, <code>relio merge --help</code>, <code>relio lint --help</code> and <code>relio db &lt;command&gt; --help</code>.</li><li>Output follows the app language; change it with the <code>RELIO_LANG</code> environment variable (<code>ko</code> · <code>en</code> · <code>ja</code> · <code>zh</code>).</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relio export ddl --input model.erm --output model.sql --db-version 17</span></span>
<span class="line"><span>relio export excel --input model.erm --output model.xlsx --template default_en</span></span>
<span class="line"><span>relio export dbml --input model.erm --output model.dbml</span></span>
<span class="line"><span>relio export mermaid --input model.erm --output - --category Sales</span></span>
<span class="line"><span>relio export json --input model.erm --output model.json --include images,history</span></span>
<span class="line"><span>relio export java --input model.erm --output-dir src --style jpa</span></span>
<span class="line"><span>relio import auto --input schema.sql --output schema.erm</span></span>
<span class="line"><span>relio diff old.erm new.erm --format markdown --output diff.md --exit-code</span></span>
<span class="line"><span>relio merge base.erm mine.erm theirs.erm -o merged.erm --report -</span></span>
<span class="line"><span>relio lint model.erm --format markdown --fail-on error</span></span>
<span class="line"><span>relio db test --db PostgreSQL --server localhost --database app --user dev --password-env PGPASSWORD</span></span>
<span class="line"><span>relio db import --db MySQL --database shop --user dev --output shop.erm</span></span></code></pre></div><h2 id="relio-export" tabindex="-1">relio export <a class="header-anchor" href="#relio-export" aria-label="Permalink to &quot;relio export&quot;">​</a></h2><p><code>relio export &lt;kind&gt; --input &lt;model.erm&gt; --output &lt;output&gt;</code></p><ul><li><strong>Kinds</strong> — <code>ddl</code> · <code>image</code> · <code>html</code> · <code>excel</code> · <code>testdata</code> · <code>dictionary</code> · <code>translation</code> · <code>java</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code>.</li><li>Without options, the last export settings saved in the <code>.erm</code> are used.</li><li>The options for each kind are in the &quot;Options by kind&quot; table below.</li><li><strong><code>--encoding</code></strong> — UTF-8 (default) · UTF-8 BOM · UTF-16LE · UTF-16BE · EUC-KR · CP949 (MS949) · Shift_JIS · GBK. An unknown name is an error (it is never silently replaced with UTF-8).</li><li><strong>Standard output</strong> — <code>--output -</code> writes to standard output for the text kinds (<code>ddl</code> · <code>dictionary</code> · <code>translation</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code>).</li><li><code>relio export ddl</code> prints one line to standard error when there are design check errors (problems that make the DDL fail when run).</li></ul><h3 id="options-by-kind" tabindex="-1">Options by kind <a class="header-anchor" href="#options-by-kind" aria-label="Permalink to &quot;Options by kind&quot;">​</a></h3><p>Every kind takes <code>--input &lt;model.erm&gt;</code>. When you do not pass an on/off option (<code>--no-…</code>), the last setting saved in the <code>.erm</code> is used.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Output</th><th>Other options</th></tr></thead><tbody><tr><td><code>ddl</code></td><td><code>--output</code></td><td><code>--db-product</code> · <code>--db-version</code> · <code>--environment</code> (tablespace environment) · <code>--category</code> · <code>--encoding</code> · <code>--line-feed</code> · <code>--comment on|off</code> (database comments) · <code>--inline-table-comment on|off</code> · <code>--inline-column-comment on|off</code> · <code>--comment-value description|logical|logical-description</code> · <code>--comment-replace-line-feed &lt;text&gt;</code> · <code>--no-comment-replace-line-feed</code> · <code>--set &lt;item&gt;=true|false</code> (each drop or create statement, can repeat) · <code>--if-not-exists</code> · <code>--omit-schema</code> · <code>--native-types</code> (boolean on Oracle 23 or later) · <code>--no-sqlblanklines</code> · <code>--drop-tablespaces</code></td></tr><tr><td><code>image</code></td><td><code>--output</code> (png, jpg, bmp or svg by extension)</td><td><code>--with-category</code> · <code>--no-with-category</code> (an image per category) · <code>--category-dir</code></td></tr><tr><td><code>html</code></td><td><code>--output-dir</code></td><td><code>--no-image</code> · <code>--no-category-image</code></td></tr><tr><td><code>excel</code></td><td><code>--output</code> (.xlsx)</td><td><code>--template default_ko|default_en|default_ja|default_zh</code> or <code>--template-file</code> · <code>--no-image</code> · <code>--logical-sheet-name</code> · <code>--physical-sheet-name</code> · <code>--category</code></td></tr><tr><td><code>dictionary</code></td><td><code>--output</code> (CSV)</td><td><code>--no-bom</code></td></tr><tr><td><code>translation</code></td><td><code>--output</code></td><td></td></tr><tr><td><code>testdata</code></td><td><code>--output-dir</code></td><td><code>--name &lt;test data name&gt;</code> (required, can repeat) · <code>--format sql|dbunit-xml|dbunit-flat-xml|dbunit-excel</code> · <code>--encoding</code></td></tr><tr><td><code>java</code></td><td><code>--output-dir</code></td><td><code>--package</code> · <code>--suffix</code> · <code>--hibernate</code> · <code>--no-hibernate</code> · <code>--style plain|jpa</code> · <code>--jpa-namespace jakarta|javax</code> · <code>--jpa-legacy-date</code> · <code>--jpa-collections</code> · <code>--jpa-fk-as-value</code> · <code>--encoding</code></td></tr><tr><td><code>dbml</code></td><td><code>--output</code></td><td><code>--no-partials</code> (writes column groups out in full) · <code>--no-notes</code> (leaves out notes)</td></tr><tr><td><code>mermaid</code></td><td><code>--output</code></td><td><code>--no-alias</code> (no logical-name aliases) · <code>--fence</code> (mermaid code block) · <code>--split-categories</code> (one <code>&lt;name&gt;-&lt;category&gt;.mmd</code> per category)</td></tr><tr><td><code>markdown</code></td><td><code>--output</code></td><td><code>--no-diagram</code> · <code>--no-views</code> · <code>--tables-only</code> · <code>--by-category</code></td></tr><tr><td><code>json</code></td><td><code>--output</code></td><td><code>--include images,history</code> · <code>--exclude layout</code> · <code>--timestamp</code> · <code>--schema-version</code> · <code>--print-schema</code> (prints the JSON Schema to standard output)</td></tr></tbody></table><p><code>dbml</code> · <code>mermaid</code> · <code>markdown</code> · <code>json</code> also take <code>--category &lt;name&gt;</code> (only that category) · <code>--encoding</code> · <code>--line-feed lf|crlf</code> (default <code>lf</code>).</p><h3 id="output-path-rules" tabindex="-1">Output path rules <a class="header-anchor" href="#output-path-rules" aria-label="Permalink to &quot;Output path rules&quot;">​</a></h3><ul><li>An existing output file is overwritten without asking, and a missing output folder is created.</li><li>If the output path is the same as the input <code>.erm</code>, nothing is written and the command fails.</li><li>Without <code>--output</code>, the path saved in the <code>.erm</code> is used — but only when it points inside the folder of the <code>.erm</code>. An absolute path outside it, another drive, a network path or <code>..</code> fails with a request to use <code>--output</code> (so an <code>.erm</code> from someone else cannot overwrite other files).</li><li>If the extension does not match the kind, a warning is shown and the file is written anyway.</li></ul><h2 id="relio-import" tabindex="-1">relio import <a class="header-anchor" href="#relio-import" aria-label="Permalink to &quot;relio import&quot;">​</a></h2><p><code>relio import &lt;format&gt; --input &lt;file|-&gt; --output &lt;new.erm&gt;</code></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td>format</td><td><code>auto</code> · <code>ddl</code> · <code>dbml</code> · <code>mermaid</code> · <code>markdown</code></td></tr><tr><td><code>--input</code></td><td>A file, or <code>-</code> (standard input)</td></tr><tr><td><code>--output</code></td><td>A new <code>.erm</code>. An existing one is overwritten only with <code>--force</code>.</td></tr><tr><td><code>--dialect</code></td><td>SQL dialect</td></tr><tr><td><code>--db</code></td><td>Database of the new document</td></tr><tr><td><code>--comment auto|description|logical</code></td><td>Whether comments go into the logical name or the description</td></tr><tr><td><code>--name-case asis|db</code></td><td>Keep unquoted names as they are, or convert them following the database&#39;s rules</td></tr><tr><td><code>--encoding</code></td><td>Input encoding</td></tr><tr><td><code>--strict</code></td><td>Nothing is created if there are warnings.</td></tr></tbody></table><p>Warnings go to standard error as <code>&lt;input&gt;:&lt;line&gt;:&lt;column&gt;: warning: &lt;message&gt;</code>. <a href="/relio/en/features/import">Import and other formats</a></p><h2 id="relio-diff" tabindex="-1">relio diff <a class="header-anchor" href="#relio-diff" aria-label="Permalink to &quot;relio diff&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>relio diff A.erm B.erm</span></span>
<span class="line"><span>relio diff --rev REV file.erm            # that version in the Git repository ↔ the disk</span></span>
<span class="line"><span>relio diff --rev REV1 --rev REV2 file.erm</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--format markdown|json|csv|sql</code></td><td><code>sql</code> is migration SQL that changes a database from A&#39;s structure to B&#39;s (same as Generate migration SQL in the comparison view)</td></tr><tr><td><code>--group-by table|kind</code></td><td>Groups Markdown by table or by type (default <code>table</code>).</td></tr><tr><td><code>--output</code></td><td>Output file; <code>-</code> for standard output</td></tr><tr><td><code>--include structure,docs,layout,settings</code></td><td>What to compare</td></tr><tr><td><code>--lang</code></td><td>Output language</td></tr><tr><td><code>--exit-code</code></td><td>Exit code 4 when there are differences</td></tr></tbody></table><p>Nothing is written to the repository and no network is used. It also works as a Git diff tool: <code>git difftool -x &quot;relio diff&quot; -- model.erm</code>. <a href="/relio/en/features/git#comparison-view">Git and merging › Comparison view</a></p><h2 id="relio-merge" tabindex="-1">relio merge <a class="header-anchor" href="#relio-merge" aria-label="Permalink to &quot;relio merge&quot;">​</a></h2><p><code>relio merge base.erm current.erm incoming.erm -o result.erm</code></p><ul><li>The result never contains conflict markers (it is always a valid <code>.erm</code>). When conflicts remain, the value from the <code>--on-conflict ours|theirs</code> side (default <code>ours</code>) is used and the command ends with exit code 5.</li><li><code>--keep-numbers ours|theirs</code> — The side whose numbers are kept.</li><li><code>--report &lt;path|-&gt;</code> · <code>--report-format markdown|json</code> — Report of conflicts and automatic items.</li><li><code>--label-base</code> · <code>--label-ours</code> · <code>--label-theirs</code> — Labels in the report.</li><li><code>--no-sort</code> — Turns off sorted saving. <code>--lang</code> — Output language.</li><li><code>-o</code> may be the same path as the current input. Nothing is written to the repository.</li></ul><h2 id="git-merge-driver" tabindex="-1">Git merge driver <a class="header-anchor" href="#git-merge-driver" aria-label="Permalink to &quot;Git merge driver&quot;">​</a></h2><p>Add one line to the repository&#39;s <code>.gitattributes</code> and register the driver in the Git configuration, and <code>git merge</code> and <code>git rebase</code> merge <code>.erm</code> files at the model level. When conflicts remain (exit code 5), Git leaves the file conflicted; open it in Relio and finish with File › Compare and merge › Resolve Git merge conflict….</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># .gitattributes</span></span>
<span class="line"><span>*.erm text eol=lf merge=relio</span></span>
<span class="line"><span></span></span>
<span class="line"><span>git config merge.relio.name &quot;Relio model merge&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Windows (Git Bash) — full path of the installed relio.exe</span></span>
<span class="line"><span>git config merge.relio.driver &#39;&quot;C:/Users/&lt;user&gt;/AppData/Local/Relio/relio.exe&quot; merge %O %A %B -o %A --label-base %S --label-ours %X --label-theirs %Y&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># when relio is on the PATH</span></span>
<span class="line"><span>git config merge.relio.driver &quot;relio merge %O %A %B -o %A --label-base %S --label-ours %X --label-theirs %Y&quot;</span></span></code></pre></div><ul><li>On Windows, write the full path of <code>relio.exe</code> in the installation folder with <code>/</code> and wrap it in quotes.</li><li><code>text eol=lf</code> in <code>.gitattributes</code> keeps line endings inside commits as LF. In teams that mix ERMaster (CRLF) and Relio (LF), this stops the whole file from showing as changed because of line endings.</li><li><code>--label-base %S</code> labels the base in the report with the common ancestor&#39;s name instead of Git&#39;s temporary file name.</li><li>The driver is Git configuration and does not travel with the repository. <strong>Everyone who merges, including teammates who use ERMaster,</strong> must register it on their own PC. Without it, <code>git merge</code> merges by line and leaves conflict markers.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>If the driver is registered but Git cannot find it (wrong path — a line such as <code>relio: command not found</code> in the output), Git marks the file conflicted but <strong>leaves only your side, with no conflict markers</strong>. Running <code>git add</code> as is would drop the incoming changes. After registering, make sure that running the path from <code>git config --get merge.relio.driver</code> as <code>&quot;…/relio.exe&quot; --version</code> prints a version number, and that <code>git check-attr merge -- model.erm</code> shows <code>merge: relio</code>.</p></div><h2 id="relio-lint" tabindex="-1">relio lint <a class="header-anchor" href="#relio-lint" aria-label="Permalink to &quot;relio lint&quot;">​</a></h2><p><code>relio lint model.erm</code></p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--format text|markdown|json</code></td><td>Output format</td></tr><tr><td><code>--output</code></td><td>Output file (default <code>-</code>, standard output)</td></tr><tr><td><code>--fail-on error|warning|info|none</code></td><td>Exit code 6 when there are findings at or above this severity (default <code>warning</code>)</td></tr><tr><td><code>--disable</code> · <code>--only</code></td><td>Comma-separated rule IDs (for example <code>pk-missing</code>, <code>fk-no-index</code>, <code>reserved-word</code>). Every rule ID is in the table in <a href="/relio/en/features/check#rules">Design check and suggestions › Rules</a>.</td></tr><tr><td><code>--db-version</code></td><td>Database version to check against</td></tr><tr><td><code>--lang</code></td><td>Output language</td></tr></tbody></table><p>Ignores made in the app are not applied, so the result is the same on every PC; turn rules off with <code>--disable</code>. <a href="/relio/en/features/check">Design check and suggestions</a></p><h2 id="relio-db" tabindex="-1">relio db <a class="header-anchor" href="#relio-db" aria-label="Permalink to &quot;relio db&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>relio db test</code></td><td>Connection test</td></tr><tr><td><code>relio db export</code></td><td>Export to a database</td></tr><tr><td><code>relio db import</code></td><td>Import from a database</td></tr><tr><td><code>relio db roundtrip</code></td><td>Round-trip test (exit code 4 when there are differences)</td></tr></tbody></table><p>Pass the password with <code>--password-env &lt;environment variable&gt;</code>. Never write the password on the command line itself. <a href="/relio/en/features/database">Databases</a></p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Success (including warnings) — with <code>diff --exit-code</code>, no differences</td></tr><tr><td>1</td><td>Input or option error (import: no tables found, or warnings with <code>--strict</code>)</td></tr><tr><td>2</td><td>Output write failure (import: an existing <code>.erm</code> without <code>--force</code>)</td></tr><tr><td>3</td><td>Cannot convert to this database</td></tr><tr><td>4</td><td>Differences found (<code>db roundtrip</code>, <code>diff --exit-code</code>)</td></tr><tr><td>5</td><td>Merge conflicts remain (<code>merge</code>)</td></tr><tr><td>6</td><td>Findings at or above the <code>--fail-on</code> level (<code>lint</code>)</td></tr></tbody></table><h2 id="using-it-in-ci" tabindex="-1">Using it in CI <a class="header-anchor" href="#using-it-in-ci" aria-label="Permalink to &quot;Using it in CI&quot;">​</a></h2><ul><li><strong>Check</strong> — <code>relio lint model.erm --fail-on error</code> fails the build when there are errors.</li><li><strong>Generate DDL</strong> — <code>relio export ddl --input model.erm --output model.sql --db-version 17</code>.</li><li><strong>Review changes</strong> — <code>relio diff --rev main model.erm --format markdown --output diff.md</code> records what changed as a document.</li><li><strong>Migration SQL</strong> — <code>relio diff before.erm after.erm --format sql --output alter.sql</code>.</li></ul>`,42)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
